
BEGIN;
ALTER TABLE public.legal_documents DROP CONSTRAINT IF EXISTS legal_documents_slug_check;
ALTER TABLE public.legal_documents ADD CONSTRAINT legal_documents_slug_check
 CHECK (slug = ANY(ARRAY['privacy-policy','terms-of-service','data-processing-agreement','cookie-policy','acceptable-use-policy']));
ALTER TABLE public.user_legal_acceptances
 ADD COLUMN IF NOT EXISTS acceptance_type text,
 ADD COLUMN IF NOT EXISTS acceptance_source text,
 ADD COLUMN IF NOT EXISTS actor_role text,
 ADD COLUMN IF NOT EXISTS action_id uuid;
ALTER TABLE public.user_legal_acceptances DROP CONSTRAINT IF EXISTS user_legal_acceptances_acceptance_method_check;
ALTER TABLE public.user_legal_acceptances ADD CONSTRAINT user_legal_acceptances_acceptance_method_check
 CHECK (acceptance_method=ANY(ARRAY['signup','required_reacceptance','privacy_preferences','institute_dpa','institute_legal_bundle']));
ALTER TABLE public.user_legal_acceptances DROP CONSTRAINT IF EXISTS user_legal_acceptances_acceptance_type_check;
ALTER TABLE public.user_legal_acceptances ADD CONSTRAINT user_legal_acceptances_acceptance_type_check
 CHECK (acceptance_type IS NULL OR acceptance_type=ANY(ARRAY['terms_acceptance','aup_acceptance','privacy_acknowledgement','dpa_acceptance']));
ALTER TABLE public.user_legal_acceptances DROP CONSTRAINT IF EXISTS user_legal_acceptances_acceptance_source_check;
ALTER TABLE public.user_legal_acceptances ADD CONSTRAINT user_legal_acceptances_acceptance_source_check
 CHECK (acceptance_source IS NULL OR acceptance_source=ANY(ARRAY['signup','login_gate','institute_creation','settings','admin']));

CREATE TABLE IF NOT EXISTS public.institute_legal_declarations(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 institute_id uuid NOT NULL REFERENCES public.institutes(id) ON DELETE RESTRICT,
 actor_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
 actor_email text NOT NULL,
 actor_role text NOT NULL CHECK(actor_role='owner'),
 declaration_type text NOT NULL CHECK(declaration_type=ANY(ARRAY['institute_authority','data_authority_attestation'])),
 declaration_text text NOT NULL,
 content_sha256 text NOT NULL CHECK(content_sha256~'^[0-9a-f]{64}$'),
 source text NOT NULL CHECK(source=ANY(ARRAY['institute_creation','login_gate'])),
 action_id uuid NOT NULL,
 accepted boolean NOT NULL DEFAULT true CHECK(accepted=true),
 accepted_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.institute_legal_declarations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.institute_legal_declarations FROM PUBLIC,anon,authenticated;
CREATE INDEX IF NOT EXISTS institute_legal_declarations_actor_idx ON public.institute_legal_declarations(actor_user_id,institute_id,accepted_at DESC);

CREATE TABLE IF NOT EXISTS private.legal_transition_config(
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton=true),
 activated_at timestamptz NOT NULL DEFAULT now(),
 grace_days integer NOT NULL DEFAULT 14 CHECK(grace_days BETWEEN 1 AND 90),
 updated_at timestamptz NOT NULL DEFAULT now()
);
REVOKE ALL ON private.legal_transition_config FROM PUBLIC,anon,authenticated;
INSERT INTO private.legal_transition_config(singleton,activated_at,grace_days) VALUES(true,now(),14) ON CONFLICT(singleton) DO NOTHING;

UPDATE public.legal_documents SET status='archived',updated_at=now()
WHERE status='published' AND locale='en-IN' AND slug IN('terms-of-service','privacy-policy','acceptable-use-policy','data-processing-agreement');
INSERT INTO public.legal_documents(slug,title,version,locale,body_markdown,content_sha256,status,is_required,is_test_only,created_at,updated_at,published_at,effective_at)
SELECT x.slug,x.title,x.version,'en-IN',x.body_markdown,
 encode(extensions.digest(concat_ws(E'\\n',x.slug,x.version,'en-IN',x.title,x.body_markdown),'sha256'),'hex'),
 'published',x.is_required,true,now(),now(),now(),now()
FROM jsonb_to_recordset('[{"slug":"terms-of-service","title":"Terms & Conditions","version":"0.4-dev","body_markdown":"# ClassBandhu — Terms & Conditions\n**Version:** 0.4 — consistency and naming revision — internal working draft  \n**Prepared:** 25 November 2026; revised 26 November 2026 (v0.4)  \n**Status:** NOT APPROVED FOR SIGNATURE OR PUBLICATION  \n**Operator:** Tirth Patel, individual operator of ClassBandhu  \n**Contact:** info.classbandhu@gmail.com  \n**Website/domain:** To be inserted after domain selection\n\n> This is a product-specific drafting draft, not legal advice. An Indian lawyer must review it against the final legal entity, consumer/e-commerce requirements (if applicable), actual product behaviour, pricing, tax treatment, service-provider contracts and applicable law. Bracketed items are deliberate approval points, not terms that may silently be assumed.\n\n## 1. About these Terms\nThese Terms govern access to and use of the ClassBandhu Tuition institute-management software service (**ClassBandhu Tuition**), related applications, support and associated services (the **Platform**). The Platform is operated by Tirth Patel, currently as an individual and not, as presently confirmed, through a registered company or LLP (**Operator**, **we**, **us**).\n\n**Product names.** *ClassBandhu* is the parent brand. These documents cover **ClassBandhu Tuition**, the ERP for tuition centres, coaching institutes and similar institutes. **ClassBandhu School** (a school ERP) is a separate product and is **not covered** unless and until school-specific versions of these documents are approved and presented. Unless the context requires otherwise, “ClassBandhu” in these documents means the brand and, where the software is meant, ClassBandhu Tuition.\n\nBy creating an account, accepting an invitation, accessing a workspace or using the Platform, the individual user agrees to the applicable terms. An institute that subscribes or creates a workspace is also bound through the authorised representative who accepts on its behalf, subject to applicable law.\n\n**Effective date:** [SET ON APPROVAL]  \n**Last updated:** [SET ON PUBLICATION]\n\n## 2. Definitions\n- **Institute** means a tuition centre or educational/coaching organisation using a separate workspace.\n- **Institute Owner** means the person authorised by the Institute to create/administer its workspace and subscription.\n- **Authorised User** means an owner, teacher, accountant or other person whom the Platform permits and the Institute authorises to use its workspace.\n- **Institute Data** means information entered or uploaded by or for an Institute, including student, parent/guardian, staff, admission, attendance, fee, payment, receipt and reminder information.\n- **Personal Data** has the meaning given under applicable data-protection law.\n- **Platform Account Data** means account, authentication, invitation, support, subscription and platform-administration information processed for operating ClassBandhu.\n- **Policies** means the Privacy Policy, Acceptable Use Policy, Institute Data Processing Agreement (DPA), and any feature-specific notice presented to the user.\n\n## 3. Eligibility, accounts and invitations\n3.1 Users must be legally capable of entering into a binding agreement and must provide accurate account details. Where an organisation is the customer, the accepting person represents that they have authority to bind it.\n\n3.2 Access is through supported account-registration and invitation workflows. The Platform may restrict registration to invited or otherwise authorised users. Users must keep authentication credentials confidential, use strong unique passwords and promptly notify the Operator of suspected compromise.\n\n3.3 An account is personal to the authorised user. Credentials must not be shared, transferred, sold or used by multiple people. Each person should use their own authorised account where the Platform supports it.\n\n3.4 The Institute Owner is responsible for authorising users, selecting appropriate roles, reviewing access, and promptly removing or disabling access when a person leaves or no longer needs it.\n\n3.5 We may verify account, institute or payment information where reasonably necessary for security, fraud prevention, billing or legal compliance.\n\n## 4. Institute workspaces and Institute responsibilities\n4.1 The Institute is responsible for the lawfulness, accuracy, relevance and appropriateness of Institute Data it enters, and for deciding which student, parent/guardian and staff information is necessary for its educational and administrative purposes.\n\n4.2 The Institute must provide appropriate privacy notices and obtain and retain any consent, authorisation or other legal basis required for its processing, including verifiable parent/lawful-guardian consent where applicable. The Institute Owner''s acceptance of a declaration in ClassBandhu is not itself the consent of a student, parent or guardian and does not prove that such consent was obtained.\n\n4.3 The Institute must ensure that it has authority to instruct the Operator to host and process Institute Data for the agreed service purposes. It must not upload data it has no right or lawful basis to provide.\n\n4.4 The Institute must use role-based access responsibly, avoid unnecessary collection, correct inaccurate records, and respond to requests from students, parents/guardians and staff concerning data it controls.\n\n4.5 The Institute must maintain its own source records and evidence of any notices, permissions or consents it is required to obtain. ClassBandhu does not independently verify each Institute''s parent/guardian consent records merely because an owner ticks a declaration.\n\n4.6 The Institute remains responsible for educational decisions, student assessment, attendance decisions, fee policies, communications and statutory/sectoral records. ClassBandhu is an administrative tool and does not replace professional or legal judgment.\n\n## 5. Platform features and service scope\nThe Platform currently supports institute administration workflows such as courses, batches, student admissions and profiles, fee balances, installment and direct fee collection, payment allocations, receipts, reminders, manual attendance and attendance reports. Platform-level functions may include institute administration, authorised platform-admin invitations, subscription billing, alerts and analytics.\n\nFeatures may change, be improved, or be retired. We will not describe a feature as available unless it is actually enabled for the relevant environment and account.\n\n**Current messaging limitation:** Student/guardian and platform subscription WhatsApp reminders are manual workflows that open WhatsApp or prepare a message for the user. Automated WhatsApp Business Cloud API delivery, automated email delivery and SMS delivery are not currently promised by these Terms.\n\n**Current attendance limitation:** Attendance is entered manually by authorised institute users. Face recognition is not a current feature. Any future biometric or automated recognition feature would require separate product, privacy, security and legal review and appropriate notices/consents and alternatives.\n\n## 6. Subscriptions, invoices and payment\n6.1 Subscription billing is intended to support monthly and yearly billing cycles. The exact plans, features, prices, applicable taxes, billing dates and payment instructions must be displayed in an order form, invoice or approved pricing page before purchase.\n\n6.2 **Commercial schedule requiring approval:**  \n- Plans and included limits: [INSERT APPROVED PLAN TABLE]  \n- Prices and currency: [INSERT]  \n- GST/tax treatment and invoice issuer details: [CONFIRM WITH ACCOUNTANT/COUNSEL]  \n- Payment methods and payment verification process: [INSERT]  \n- Refund/cancellation policy: [APPROVE]  \n- Support channel and service hours: [APPROVE]\n\n6.3 Unless an order form says otherwise, subscription payment is collected manually and an invoice/receipt is issued or recorded by the Operator. For grace-period protection, the relevant payment date is the date on which the amount is successfully transferred/credited to the designated payment destination, evidenced by a reliable transaction record. The Operator may verify the transaction after that date. A screenshot or payment claim without a verifiable successful transaction is not, by itself, proof of payment.\n\n6.4 The Institute must pay undisputed invoices by the due date and provide accurate billing/contact details. If an invoice is disputed, the Institute should promptly provide the reason and supporting details; undisputed amounts remain payable.\n\n6.5 **Seven-day grace period (proposed operational rule):** The due date is day zero. The Institute has seven (7) full calendar days after the due date to make payment. Unless the invoice expressly states a different approved timezone, the deadline is 23:59:59 India Standard Time (IST; Asia/Kolkata) on the seventh calendar day after the due date. Weekends and public holidays count as calendar days. The timezone and exact billing configuration must be confirmed before this clause is activated in the product.\n\n6.6 A successful payment made by the deadline will protect the Institute from non-payment suspension while the Operator completes reasonable verification, provided the Institute submits the transaction evidence described below by the deadline. Verification delay alone must not cause suspension. For this clause, **transaction evidence** means the payment-provider, bank or payment-channel generated transaction reference (such as a UTR, UPI transaction ID, RRN or equivalent bank/payment reference), the amount paid, the transaction date (and time where available), the payment channel, the intended recipient/payee, and a transaction status or record reasonably showing that the transfer was successful or completed. Where a payment channel does not issue a UTR, UPI ID or RRN, an equivalent provider-generated reference or relevant bank-statement entry may be supplied. A screenshot may support the evidence but, by itself, is not sufficient unless it displays verifiable provider-generated transaction details. The Institute must not send passwords, PINs, OTPs, full card details or other authentication secrets. If the payment is later shown to have failed, been reversed or not reached the designated destination, the Operator will notify the Institute, provide the verification basis where reasonably possible, and allow five (5) calendar days to resolve or replace the payment before non-payment suspension, unless urgent fraud/security action is justified.\n\n6.7 A partial payment does not automatically satisfy the invoice. Unless a written payment arrangement says otherwise, the unpaid balance remains due. Before suspending for a partial payment, the Operator must identify the remaining amount and give notice. A bona fide invoice dispute must be submitted in writing before the grace-period deadline, identify the specific invoice item and amount disputed, explain the grounds with reasonable supporting material, and confirm payment of the undisputed portion by the applicable due date or grace-period deadline. A dispute that does not meet these conditions does not pause suspension for the unpaid amount. The Operator will acknowledge a qualifying dispute within two (2) business days and complete an initial review within five (5) business days after receiving the required information. If reasonably necessary, the Operator may extend the review once by up to five (5) further business days, notifying the Institute before the initial review period ends and giving a brief reason. For this clause, a **business day** means a day other than a Sunday or a public holiday on which banks are generally open for business in India. The disputed amount alone will not be a basis for non-payment suspension while this time-limited review is pending, subject to fraud/security exceptions and applicable law. If the dispute is rejected in whole or in part, the Operator will explain the decision and identify the amount payable; the Institute must pay that amount within five (5) calendar days after the decision notice, failing which suspension may proceed after notice. If the Operator has not issued a decision by the end of the maximum ten (10) business-day review period, the Operator must send a status notice; the disputed amount may then be treated as unpaid for suspension purposes only after a further five (5) calendar days'' written notice. This does not determine the merits of the dispute, waive either party''s legal rights, or prevent the Institute from pursuing the dispute through the contract''s dispute-resolution route. The review pause therefore has a defined maximum and does not create an indefinite payment holiday.\n\n6.8 The Operator will send a payment reminder before the end of the grace period, with a target reminder around three calendar days before the deadline and, where operationally available, a final reminder on the deadline day. Reminder timing/channel is an operational target, not a guarantee until implemented and tested.\n\n6.9 After the grace period, suspension may apply only where the relevant amount remains unpaid and no timely successful payment is awaiting verification or qualifying invoice dispute is unresolved. Suspension restricts ordinary workspace operations; it does not delete Institute Data. The Institute must retain a route to contact support/privacy requests and request an available data export. Export is subject to identity/authority verification, security controls, technical capability, legal holds and any lawful financial/audit restrictions; do not promise an unverified format or instant export.\n\n6.10 We will restore access promptly after the overdue amount is verified as paid, subject to reasonable security checks. No automatic deletion of Institute Data occurs merely because an invoice is overdue or an Institute is suspended.\n\n6.11 Any late fee, interest, tax, refund, pro-rata credit or cancellation charge must be expressly stated in the approved pricing/order terms. None is created by this draft.\n\n## 7. Acceptable use and prohibited conduct\nUsers must comply with the Acceptable Use Policy. Without limitation, users must not:\n- access another Institute''s workspace or data without authority;\n- bypass authentication, role checks, tenant isolation or other security controls;\n- use another person''s credentials or invite unauthorised persons;\n- upload unlawful, misleading, excessive or irrelevant personal data;\n- misuse student, child, parent/guardian or staff information;\n- use the Platform for harassment, discrimination, threats, spam, fraud or unlawful surveillance;\n- probe, scan, disrupt, reverse engineer or overload the Platform except where expressly permitted by law or written authorisation;\n- introduce malware, malicious code or harmful content;\n- falsify payments, receipts, attendance, audit records or identity information;\n- use the Platform to violate intellectual-property, privacy or other legal rights.\n\n## 8. Privacy and data processing\n8.1 The Privacy Policy explains how the Operator handles personal data for Platform accounts, security, platform billing, support and other Operator-controlled purposes.\n\n8.2 For Institute Data, the Institute will generally determine the educational/administrative purposes and the Operator may process the data on the Institute''s documented instructions as a service provider/Data Processor. The actual legal roles depend on the purpose and applicable law. The Operator may act independently for account administration, security, platform billing and support.\n\n8.3 **The Institute DPA is mandatory for every Institute workspace.** Every Institute using ClassBandhu may enter or process personal data through the service, including student, parent/guardian, staff or other Institute Data; therefore, no Institute is offered a “no DPA applies” path under this draft. The DPA is presented as a clearly identified linked document within checkbox 1 of the three Institute-creation declarations. It is not a fourth checkbox. Before acceptance, the Institute must be shown the DPA title, version and full text. The same checkbox action must create separate evidence identifying the DPA version and content hash. The DPA supplements these Terms and prevails for the subject matter of processing activities it governs if there is a conflict. Counsel must confirm the legal character and enforceability of this bundled acceptance before publication or activation.\n\n8.4 **Existing Institutes and owner changes.** An Institute workspace created before this DPA mechanism is activated, and any Institute whose Institute Owner changes, must also be covered by the DPA. The Institute Owner must accept the same document bundle and make the same three declarations for that Institute through a one-time login confirmation step (Consent Implementation Specification §5.5). Staff users such as teachers and accountants cannot accept the DPA or make these declarations for an Institute, and a Super Admin cannot accept on an owner''s behalf. The transition period and notices before workspace access is restricted if the confirmation is not made are **[TRANSITION PERIOD AND NOTICE — TO BE APPROVED]**. Counsel must advise on the position for any processing that occurs before acceptance.\n\n8.4 The Institute must not treat acceptance of the Privacy Policy or these Terms as blanket consent from students, parents/guardians or other data subjects.\n\n8.5 The Operator will not claim that the Platform is “100% secure”, certified, DPDP-compliant in every respect, or subject to a specific uptime/backup guarantee unless that claim has been independently verified and expressly documented.\n\n## 9. Intellectual property and licence\n9.1 The Operator retains rights in the Platform software, interface, design, branding, documentation and related materials, except for third-party components and rights belonging to others.\n\n9.2 Subject to these Terms and payment of applicable fees, the Operator grants the Institute a limited, non-exclusive, non-transferable, revocable licence during the subscription term for its authorised users to access and use the Platform for the Institute''s internal educational and administrative purposes.\n\n9.3 The Institute retains its rights in Institute Data. The Institute grants the Operator a limited right to host, reproduce, transmit, back up (where configured), display and otherwise process Institute Data only as reasonably necessary to provide, secure, support and maintain the Platform, comply with law, and follow documented instructions.\n\n9.4 Users must not remove proprietary notices, copy or resell the Platform, or use the Platform to build a competing service except to the extent such restriction is prohibited by applicable law.\n\n## 10. Availability, maintenance and support\n10.1 The Platform is provided on an evolving SaaS basis. We may perform maintenance, updates, security fixes and emergency changes. Some interruptions may occur.\n\n10.2 No uptime percentage, recovery time objective, recovery point objective, backup frequency or support response time is promised by this draft. Any service-level commitment must be separately approved and documented.\n\n10.3 We will use reasonable operational efforts to address reported issues, but support hours, priority levels and response targets remain to be approved: [INSERT SUPPORT POLICY].\n\n10.4 The Institute is responsible for maintaining appropriate independent records and exports for its critical business operations where the Platform provides an export facility. Do not assume that a particular backup or restore capability exists unless it is verified and documented.\n\n## 11. Suspension and termination\n11.1 We may restrict or suspend access where reasonably necessary to protect the Platform, users or data; respond to suspected compromise; enforce these Terms; comply with law; address non-payment after the agreed grace period; or prevent material harm.\n\n11.2 Where practicable, we will provide notice and an opportunity to resolve the issue before suspension, except where immediate action is necessary for security, legal or operational reasons.\n\n11.3 Suspension for non-payment does not itself authorise deletion of Institute Data. During suspension, ordinary access may be limited while data remains preserved subject to the applicable retention and legal-hold rules. The Institute Owner must still be able to contact the Operator about privacy/deletion requests and request an available export through a verified support route. Any export limitations must be explained; suspension must not be used to obstruct a lawful request.\n\n11.4 Either party may terminate under the approved order terms or where the other party materially breaches these Terms and fails to cure the breach within [CURE PERIOD TO APPROVE], if a cure is possible.\n\n11.5 On termination, the Institute may request export/return of available Institute Data within [EXPORT WINDOW TO APPROVE], subject to technical capability, payment status, security verification, legal obligations and the DPA. Any deletion timetable must follow the approved retention schedule and must account for backups and legal holds.\n\n11.6 We may retain records that must be kept for tax, accounting, fraud prevention, dispute resolution, security, legal compliance or establishment/exercise/defence of legal claims. Retained records should be access-restricted and not used for unrelated purposes.\n\n## 12. Disclaimers\nTo the extent permitted by law, the Platform is provided on an “as available” basis. We do not warrant that it will be uninterrupted, error-free or suitable for every Institute''s specific legal, educational, accounting or regulatory requirements. The Institute must independently verify financial, attendance and student records and maintain any legally required records.\n\nNothing in these Terms excludes a consumer or other right that cannot lawfully be excluded.\n\n## 13. Liability\nThe allocation and cap of liability requires Indian counsel review and commercial approval. **Do not publish a numeric cap or broad exclusion until approved.**\n\nSubject to applicable law, neither party should be liable for indirect or consequential loss to the extent such exclusion is legally enforceable. Any agreed cap, carve-outs (including confidentiality, data protection, IP infringement, fraud, wilful misconduct, unpaid fees and statutory liabilities), and treatment of data loss must be set out in a signed/approved version: [LEGAL REVIEW REQUIRED].\n\n## 14. Changes to the Platform or Terms\nWe may update features and these Terms. We will publish a new version and effective date. Where required, we will give notice and obtain renewed acceptance before continued access. Material changes to processing purposes will be handled through the Privacy Policy and appropriate notices/consents, not by silently relying on acceptance of a general update.\n\n## 15. Governing law and disputes\n**Requires counsel and operator approval before publication.** Proposed governing law: laws of India. Proposed courts/venue: [SELECT APPROPRIATE JURISDICTION AFTER LEGAL REVIEW]. The parties should first attempt good-faith resolution through the official contact email. Nothing here removes mandatory statutory remedies or jurisdiction.\n\n## 16. Contact\nFor account, subscription, legal or privacy questions:\n\n**Tirth Patel — ClassBandhu**  \n**Email:** info.classbandhu@gmail.com\n\nNo home or postal address is included in this draft. Counsel must separately confirm whether a particular mandatory disclosure applies and advise on a privacy-preserving compliant approach.\n","is_required":true},{"slug":"privacy-policy","title":"Privacy Policy","version":"0.10-dev","body_markdown":"# ClassBandhu Tuition — Privacy Policy Draft v0.10\n\n**Status: INTERNAL WORKING DRAFT — NOT FOR PUBLICATION**\n\nPrepared 25 November 2026; aligned with legal pack v0.4 on 26 November 2026. This draft is based on the currently inspected development source and database metadata. It is not legal advice and must be reviewed by an Indian privacy lawyer before publication.\n\n**Confirmed operator details**\n- Brand: ClassBandhu (parent brand). This policy covers **ClassBandhu Tuition**. **ClassBandhu School** is a separate product and is not covered until its own policy is approved.\n- Operator: Tirth Patel (individual operator; no company/LLP currently confirmed)\n- Privacy contact: info.classbandhu@gmail.com\n- Public postal address: intentionally omitted at the operator''s request; counsel should confirm whether any particular mandatory disclosure applies before publication.\n\n**Publication blockers**\n1. Select and verify the public website domain.\n2. Confirm provider/subprocessor list, provider contracts, hosting/backup/support locations and Netlify processing. Both Supabase project metadata records inspected (development and production) show Tokyo (`ap-northeast-1`); this is not a complete map of every processing location.\n3. Approve retention periods for each data category, including student/attendance/financial records, audit events, invitation records, migration anomaly data, and backups.\n4. Confirm Data Fiduciary/Data Processor allocation by processing purpose. The Institute Data Processing Agreement is mandatory for every Institute and is accepted through checkbox 1 (Terms §8.3).\n5. Define rights-request and grievance response workflow and a realistic service target.\n6. Confirm the website enquiry form and actual data fields before including website enquiry data as an active collection practice.\n7. Complete technical review of the student `address` field, which the inspected development code currently populates with a generic placeholder rather than a user-provided address.\n8. Replace the legacy EduLedger legal pages and product naming (use ClassBandhu / ClassBandhu Tuition) and footer/contact references; no such change has yet been made to the application.\n9. Approve the transition period and notices for existing Institutes and owner changes (Spec §5.5).\n10. Approve the final public wording for the ClassBandhu / ClassBandhu Tuition / ClassBandhu School names.\n\n---\n\n# Privacy Policy\n\n**Effective date:** To be set on publication  \n**Last updated:** 25 November 2026 (working draft; update on approval)  \n**Service:** ClassBandhu Tuition, part of the ClassBandhu brand (the “Platform”)  \n**Website:** [PUBLIC WEBSITE DOMAIN — TO BE SELECTED]  \n**Operator:** Tirth Patel, individual operator of ClassBandhu (not currently a registered company/LLP, as confirmed by the owner)  \n**Privacy contact:** info.classbandhu@gmail.com  \n**Grievance contact:** Tirth Patel — info.classbandhu@gmail.com\n\n### 1. Who this policy applies to\n\nThis Privacy Policy explains how `Tirth Patel, operating ClassBandhu` (“we”, “us” or “our”) handles personal data in connection with ClassBandhu Tuition, including:\n- our public website and enquiry channels;\n- the tuition/institute management ERP and related services;\n- user accounts, institute workspaces and platform administration;\n- support, onboarding, subscription and billing communications.\n\nThe Platform is designed for institutes and their authorised users. Institutes may enter information about students, parents/guardians, teachers and other individuals. If you are a student or parent/guardian whose information has been entered by an institute, please contact that institute first for questions about the institute''s use of your information. You may also contact us using the details above where we process information on the institute''s behalf or where the law permits/directs you to contact us.\n\nClassBandhu School, if launched, is a separate product and is not covered by this policy. Students and parents/guardians do not currently have ClassBandhu Tuition logins; their information is entered and managed by the institute''s authorised users.\n\n### 2. Our role and the institute''s role\n\nFor information an institute uploads or manages for its educational and administrative purposes (for example, student admissions, attendance and tuition-fee records), the institute will generally determine why and how that information is used. Depending on the actual arrangement, the institute may act as the Data Fiduciary/controller and we may process the information as its service provider/Data Processor.\n\nWe may separately determine purposes and means for information needed to create and secure Platform accounts, administer our own subscriptions and invoices, manage platform administrators, protect the Platform, provide support and operate our public website. For those activities, we may act as the relevant Data Fiduciary/controller.\n\nThe allocation is set out in the Terms and in the Institute Data Processing Agreement, which every institute must accept before using the Platform. We will not describe ourselves as only a processor for all data if our actual activities make us a separate fiduciary for particular purposes.\n\n### 3. Personal data we may process\n\nDepending on the features an institute uses and the information it enters, categories may include:\n\n1. **Account data:** name, email address, authentication/account identifiers, account status, password-authentication data handled through the authentication provider, account recovery and invitation records.\n2. **Institute data:** institute name, contact details, profile and operational settings.\n3. **Student and education data:** student identifiers and profile/admission information, course and batch membership, roster details, attendance records and reports. The exact fields depend on the institute''s configuration and must be confirmed against the live application.\n4. **Parent/guardian and contact data:** contact details supplied by the institute for student administration or communications, where the feature is used.\n5. **Financial and fee data:** course fee obligations, installments, payments, payment references, outstanding balances, receipts, reversals and related financial history.\n6. **Communication data:** reminder recipient/contact details, invoice billing contacts and the information needed to prepare manual WhatsApp reminder links/messages.\n7. **Subscription and platform billing data:** subscription periods, invoices, due dates, billing contacts and platform-level records.\n8. **Security and operational data:** role and membership information, authentication/session events, audit/security records, diagnostic and service-health information. Specific IP address, device, browser and log fields must be confirmed before publication.\n9. **Website enquiry data:** if and when the public website enquiry form is launched, details such as name, institute, role, email, phone number and message may be collected to respond to enquiries. [DRAFTING NOTE: keep this item only once the enquiry form and its notice are live.]\n10. **Legal acceptance records:** the user and institute concerned, the document name, version and content hash accepted, the declaration made, the server date/time and the acceptance source, kept so we can show what was agreed.\n\nWe do not intend to collect more personal data than is reasonably needed for the stated purposes. Do not upload sensitive identity documents or unrelated personal information unless the Platform expressly supports it and the institute has a lawful reason to do so.\n\n### 4. Why we use personal data\n\nSubject to the applicable legal basis and the institute''s instructions, information may be used to:\n- create and authenticate user accounts;\n- provide access to institute workspaces and authorised Platform features;\n- manage courses, batches, admissions, student records and attendance;\n- calculate tuition-fee obligations, installments, payments and outstanding balances;\n- create receipts and maintain transaction history;\n- prepare user-initiated/manual fee reminders and platform billing reminders;\n- manage institutes, platform administrators, subscriptions, invoices and billing;\n- maintain tenant separation, enforce roles and permissions, and protect accounts and records;\n- diagnose errors, maintain availability, investigate misuse and improve reliability;\n- respond to support requests, enquiries and complaints;\n- keep evidence of the policies, agreements and declarations accepted;\n- comply with applicable law, enforce agreements and resolve disputes.\n\nWe will not use student data for targeted advertising or unrelated profiling. [DRAFTING NOTE: do not claim analytics, advertising cookies or AI training unless introduced and separately disclosed.]\n\n### 5. Student information and children\n\nInstitutes must only enter student and guardian information they are authorised to provide and use. Where a student is a child under applicable law, the responsible Data Fiduciary must identify and fulfil any applicable requirement for verifiable parent/lawful-guardian consent before processing. The institute must provide appropriate notices to parents/guardians and students as required. The DPDP Rules include limited, conditional exemptions for specified educational-institution activities; these are not a blanket exemption for every student record or every SaaS provider. ClassBandhu must not assume it can rely on an institute''s exemption without legal analysis of the parties, purposes and conditions.\n\nAn institute owner''s acceptance of our Platform Terms or Privacy Policy does not by itself prove that every student or parent/guardian has consented to the institute''s collection or our processing. We will work with institutes to document the respective responsibilities in the Institute Data Processing Agreement and onboarding materials.\n\nThe institute''s authorised users, not ClassBandhu, collect information about students and parents/guardians. ClassBandhu School, if launched, will need its own review because it is likely to involve more children''s data.\n\nThe current attendance workflow is manual. QR/barcode attendance is only a possible future feature, and face recognition is not represented as a current feature. Any future biometric or facial-recognition processing would require a separate assessment, clear notice, lawful basis/consent where required, security and retention controls, and an accessible non-biometric alternative where appropriate.\n\n### 6. WhatsApp and other communication channels\n\nThe current Platform supports user-initiated/manual WhatsApp reminders by opening WhatsApp with a prepared link or message. Platform subscription billing reminders may also be prepared for manual sending. The Platform does not currently claim to deliver messages automatically through the WhatsApp Business Cloud API. Automated WhatsApp API, email and SMS delivery are future/deferred capabilities.\n\nWhen a user chooses to open WhatsApp or send a message, WhatsApp and its relevant service providers process information under their own terms and privacy policy. The sender is responsible for checking the recipient, message and contact details before sending. We do not control WhatsApp''s independent processing.\n\n### 7. Sharing and service providers\n\nWe may disclose or make personal data available:\n- to the institute and users authorised by that institute;\n- to infrastructure and service providers that host, authenticate, secure or support the Platform, such as Supabase and Netlify, subject to verification of the actual services and contractual terms;\n- to communication providers when a user independently chooses to open or send a WhatsApp message;\n- to professional advisers, auditors or insurers where reasonably necessary;\n- to public authorities, courts or regulators where required by law or valid legal process;\n- in connection with a merger, acquisition or business transfer, subject to appropriate safeguards and applicable law.\n\nWe do not sell personal data. [DRAFTING NOTE: hosting and authentication providers are necessary, so do not promise that no third party processes data. Before publication, list the actual subprocessors, purposes, locations and privacy links, or give a clear route to obtain them.]\n\n### 8. Data location and international processing\n\nThe Platform uses Supabase and Netlify. The actual hosting regions, backup locations, support access locations and cross-border transfers must be verified from the active project configuration and provider terms. We will not promise that all data stays in India unless that is verified and contractually supported. Any transfer will be handled in accordance with applicable law and our agreements.\n\n### 9. Security\n\nWe use technical and organisational measures appropriate to the nature of the Platform, which is designed around authenticated access, role-based permissions, database-level access controls and separation of institute workspaces. Measures may include access restrictions, secure configuration, monitoring and backups where configured.\n\nNo online service can guarantee absolute security. [DRAFTING NOTE: claim no certifications, encryption standards, penetration-test status, backup frequency or recovery guarantees unless verified.] Institutes are responsible for using strong unique passwords, protecting devices and credentials, promptly removing access for former staff and notifying us of suspected unauthorised access.\n\nPlatform administrator accounts are intended to manage platform-level records (institutes, subscriptions, invoices) and are restricted from routine access to institute student records. [VERIFY AGAINST THE APPLICATION BEFORE PUBLICATION.]\n\n### 10. Retention and deletion\n\nWe retain personal data only for as long as reasonably necessary for the purpose for which it was collected, to provide the service, maintain legitimate business records, resolve disputes, enforce agreements, protect security and comply with applicable law.\n\nRetention periods differ by category. Student records, attendance, payment and receipt histories may be controlled by the institute and may need to be retained for educational, accounting, tax, dispute or legal purposes. Account, subscription, invoice, security and audit records may also have separate retention requirements.\n\nWhen an institute requests deletion or closes its account, we will assess the request, the institute''s instructions, applicable law, financial-record obligations, backups and any legal hold. Some records may be retained or restricted rather than immediately erased. We will document a category-specific retention schedule before publication and will not promise instant deletion from all backups unless the technical process supports it.\n\nLegal acceptance records are kept as minimal, access-restricted evidence and are not deleted automatically on a deletion request; each request is reviewed for necessity and legal basis.\n\n### 11. Subscription non-payment, suspension and your data\n\nIf an institute''s subscription is unpaid after the grace period set out in the Terms, its workspace may be suspended. Suspension restricts access; it does not by itself delete data. A suspended institute can still contact us to request export or deletion, and a deletion request is handled under the retention process above, not by automatic erasure.\n\n### 12. Your rights and requests\n\nSubject to applicable law and the role we play for the relevant data, individuals may have rights to request information about processing, correction, completion, updating, erasure, withdrawal of consent and grievance redressal.\n\nFor student records controlled by an institute, requests should normally be directed to that institute. We will assist the institute where we act as its processor and respond directly where we are responsible for the relevant processing. Requests can be sent to `info.classbandhu@gmail.com` with enough information to verify the requester''s identity and locate the relevant account/record. Do not send passwords or unnecessary identity documents by email.\n\nWhere processing is based on consent, a person may withdraw consent through a route that is as easy to use as the route used to give it, subject to applicable law. Withdrawal does not make prior lawful processing unlawful and may affect the availability of a feature or service.\n\n### 13. Complaints and privacy contact\n\nFor privacy questions, data requests or complaints, contact:\n\n- Privacy contact: Tirth Patel\n- Email: `info.classbandhu@gmail.com`\n- Response target: `[OPERATIONAL SLA TO BE APPROVED]`\n\nWe will acknowledge and handle requests under the applicable law and published grievance process. [DRAFTING NOTE: do not publish an unsupported response deadline.]\n\n### 14. Cookies and similar technologies\n\nThe public website and ERP may use essential technologies needed for authentication, security, session continuity and core functionality. Whether analytics, advertising or other optional cookies are used must be verified. If optional analytics or marketing tools are introduced, disclose them and implement an appropriate consent/preference mechanism where required. Publish a separate Cookie Policy if non-essential cookies or tracking are used.\n\n### 15. Changes to this policy\n\nWe may update this Policy to reflect changes in the Platform, our practices or applicable law. We will publish the updated version and its effective date. Where a change materially affects the purposes or manner of processing and renewed notice or consent is required, we will provide the appropriate notice and obtain the required consent before continuing that processing.\n\n### 16. Contact\n\nFor privacy matters, contact Tirth Patel at info.classbandhu@gmail.com. [DRAFTING NOTE: no postal address is included by the operator''s choice; counsel to confirm whether any disclosure is mandatory.]\n\n---\n","is_required":true},{"slug":"acceptable-use-policy","title":"Acceptable Use Policy","version":"0.4-dev","body_markdown":"# ClassBandhu — Acceptable Use Policy\n**Version:** 0.4 — consistency and naming revision — internal working draft  \n**Prepared:** 25 November 2026; revised 26 November 2026 (v0.4)  \n**Status:** NOT APPROVED FOR PUBLICATION  \n**Operator:** Tirth Patel  \n**Contact:** info.classbandhu@gmail.com  \n**Applies to:** ClassBandhu Tuition. ClassBandhu School is a separate product and is not covered until a school-specific policy is approved.\n\n## 1. Purpose and scope\nThis Acceptable Use Policy (**AUP**) applies to every person who accesses ClassBandhu, including Institute Owners, teachers, accountants, other authorised Institute users and platform administrators. It supplements the Terms & Conditions and Privacy Policy. If a stricter legal or security requirement applies, that requirement controls.\n\nClassBandhu is an administrative platform for tuition/institute workflows. Access is limited to legitimate, authorised educational and administrative purposes.\n\n## 2. Account and access security\nUsers must:\n- use only their own account and never share passwords or authentication tokens;\n- keep credentials, devices and recovery channels secure;\n- use strong unique passwords and any additional security controls made available;\n- sign out from shared devices and protect devices against unauthorised access;\n- promptly report suspected account compromise, lost devices or unauthorised access;\n- ensure that each staff member has their own account where supported;\n- use only the roles and permissions assigned by the Institute.\n\nInstitute Owners must review users and permissions periodically and remove access promptly when a staff member leaves or changes responsibilities.\n\n## 3. Institute and tenant boundaries\nUsers must not:\n- access, attempt to access, enumerate or infer another Institute''s workspace or records;\n- use another Institute''s credentials, identifiers, invitations or exports;\n- bypass or test tenant isolation, role checks, RLS, authentication or administrative controls without written authorisation;\n- share Institute Data with another Institute or an unauthorised third party;\n- use Super Admin or support privileges to inspect Institute content for curiosity or unrelated purposes.\n\nAny suspected cross-Institute exposure must be reported immediately.\n\n## 4. Student, child and parent/guardian data\nUsers must:\n- enter only information reasonably necessary for the Institute''s educational/administrative purpose;\n- provide required privacy notices and obtain legally required authority/consent before entering data;\n- maintain evidence of parent/lawful-guardian consent where applicable;\n- avoid collecting sensitive identity, health, biometric or other high-risk data unless the feature, purpose and legal basis have been separately assessed and approved;\n- keep student contact details, addresses, fee information, attendance and reports confidential;\n- share/export student records only with people who have a legitimate need and authority;\n- correct inaccurate or outdated information;\n- respond appropriately to student, parent/guardian and staff privacy requests.\n\nThe Institute Owner''s click-through declaration is not a substitute for each parent''s or guardian''s consent where required.\n\n## 5. Financial and attendance integrity\nUsers must not falsify or manipulate:\n- student fee balances, payments, allocations, reversals or receipts;\n- subscription invoices or payment confirmation;\n- attendance dates, statuses, correction requests or audit history;\n- admission, student or Institute identity details.\n\nUsers must not use another person''s payment confirmation or receipt. Financial discrepancies should be reported through the Institute''s authorised administrator and support route.\n\n## 6. Messaging and communications\nCurrent WhatsApp reminder features are manual. Users are responsible for checking the recipient and message content before sending. Users must:\n- send only appropriate, lawful and relevant communications;\n- respect opt-outs and communication preferences where applicable;\n- avoid spam, threats, harassment, coercion or disclosure of another student''s information;\n- verify that the phone number belongs to the intended recipient;\n- not imply that a manual WhatsApp link means ClassBandhu automatically delivered or verified the message.\n\nAutomated WhatsApp Business API, email or SMS delivery is not promised as a current feature.\n\n## 7. Prohibited content and conduct\nUsers must not use ClassBandhu to:\n- commit or facilitate unlawful activity, fraud, identity theft or financial deception;\n- harass, threaten, discriminate against, exploit or abuse any person;\n- upload malware, malicious scripts or harmful files;\n- distribute spam, phishing, scams or unsolicited bulk messages;\n- upload content that infringes intellectual-property, privacy or publicity rights;\n- conduct unauthorised surveillance or profiling;\n- expose children''s personal information publicly or unnecessarily;\n- upload data obtained unlawfully or without authority;\n- impersonate another person, Institute or official;\n- interfere with availability, integrity or security of the Platform.\n\n## 8. Technical restrictions\nExcept where expressly authorised in writing or permitted by applicable law, users must not:\n- probe, scan, penetrate, stress-test or exploit the Platform;\n- reverse engineer, decompile or attempt to derive source code;\n- scrape, harvest or bulk-extract data;\n- circumvent rate limits, access controls or security safeguards;\n- introduce code, bots or automation that degrades service or accesses data beyond the user''s permissions;\n- test production systems using real personal data without approval.\n\nSecurity researchers should contact info.classbandhu@gmail.com before conducting testing and must obtain written scope and permission.\n\n## 9. Data exports, devices and local copies\nExports may contain sensitive student and financial information. Users must:\n- export only what is needed;\n- store exports on access-controlled devices and approved locations;\n- avoid public links, personal social accounts or shared unsecured folders;\n- delete unnecessary local copies securely;\n- not transfer records to personal accounts or third parties without authority;\n- promptly report lost or exposed exports.\n\n## 10. Reporting a violation\nReport suspected misuse, security vulnerabilities, accidental disclosure or policy violations to **info.classbandhu@gmail.com**. Include the relevant Institute/workspace, approximate time, affected feature and a concise description. Do not send passwords or unnecessary student records in the initial report.\n\n## 11. Enforcement\nDepending on severity and applicable law, the Operator may investigate, preserve relevant evidence, restrict a session, suspend an account or workspace, disable an invitation, or take other proportionate steps to protect users and the Platform. Where practicable, the affected Institute will be notified and given an opportunity to respond. Immediate action may be necessary to prevent harm, address compromise or comply with law.\n\nSuspension for non-payment follows the separate Terms and the agreed seven-day grace period. Suspension does not itself mean that Institute Data is deleted.\n\n## 12. Changes\nThis AUP may be updated as the Platform and legal requirements evolve. Material changes will be versioned and users will be asked to accept the current required version where appropriate.\n\n## 13. Contact\nTirth Patel — ClassBandhu  \ninfo.classbandhu@gmail.com\n\nNo home or postal address is included in this working draft. Counsel must confirm any specific mandatory disclosure before publication.\n","is_required":true},{"slug":"data-processing-agreement","title":"Institute Data Processing Agreement","version":"0.4-dev","body_markdown":"# ClassBandhu — Institute Data Processing Agreement (DPA)\n**Version:** 0.4 — consistency and naming revision — internal working draft  \n**Prepared:** 25 November 2026; revised 26 November 2026 (v0.4)  \n**Status:** NOT APPROVED FOR SIGNATURE  \n**Proposed provider:** Tirth Patel, individual operator of ClassBandhu  \n**Contact:** info.classbandhu@gmail.com\n\n> This draft assumes a common SaaS arrangement in which the Institute determines the purposes and essential means of processing student/parent/staff records and ClassBandhu processes those records to provide the ERP. This is not automatically true for every data category or purpose. Indian counsel must validate the roles, statutory terminology, contract structure and actual provider terms before signature.\n\n## 1. Parties and relationship\nThis DPA is between:\n- **Institute / Customer:** the organisation identified in the applicable order, workspace or acceptance record (**Institute**); and\n- **Service Provider:** Tirth Patel, operating ClassBandhu (including ClassBandhu Tuition) as an individual (**Provider**).\n\nThis DPA covers **ClassBandhu Tuition** only. ClassBandhu School, if launched, requires its own or an updated DPA.\n\nThe Institute and Provider are each a **Party** and together the **Parties**.\n\nThis DPA supplements the ClassBandhu Terms & Conditions. It applies only to personal data the Provider processes on behalf of the Institute for providing the subscribed Platform services (**Customer Personal Data**). It does not automatically govern data for which the Provider independently determines the purpose and means, such as its own account administration, platform subscription billing, security and direct support records.\n\n## 2. Roles and scope\n2.1 The Institute is expected to act as the Data Fiduciary/controller for Institute Data where it decides why and how student, parent/guardian, staff and educational-administration information is processed.\n\n2.2 The Provider acts as a Data Processor/service provider only to the extent it processes Customer Personal Data on the Institute''s documented instructions and does not determine an independent purpose.\n\n2.3 If the Provider determines purposes for a particular processing activity, the Parties must document that activity and the Provider''s independent role in the Privacy Policy or a separate notice. Labels in this DPA do not override the actual facts or applicable law.\n\n2.4 The Provider will process Customer Personal Data to host, operate, secure, maintain and support the Platform; enable authorised Institute users to manage courses, batches, student admissions, profiles, fees, payments, receipts, attendance and reminders; and perform other functions expressly enabled and instructed by the Institute.\n\n## 3. Processing details\nThe processing particulars are set out in Annex 1 and may be updated by written agreement or a versioned annex.\n\n## 4. Institute instructions and responsibilities\n4.1 The Provider will process Customer Personal Data only on documented instructions from the Institute, including instructions arising from authorised user actions and configuration of the Platform, unless applicable law requires otherwise. If legally permitted, the Provider will inform the Institute of such legal requirement before processing.\n\n4.2 The Institute is responsible for:\n- determining and documenting lawful purposes and legal bases;\n- providing legally required notices to students, parents/guardians, staff and other data subjects;\n- obtaining and retaining consent/authorisation where required, including verifiable parent/lawful-guardian consent where applicable;\n- ensuring that its workspace users are authorised and assigned appropriate roles;\n- ensuring data is relevant, accurate and not excessive;\n- responding to requests from data subjects where the Institute is the responsible Data Fiduciary;\n- deciding retention periods for Institute records, subject to applicable law and the agreed service capabilities;\n- maintaining independent evidence of consent/notice/authorisation where required.\n\n4.3 An Institute Owner''s declaration that the Institute has authority and has obtained required permissions is a contractual attestation only. It does not constitute the parent''s or guardian''s consent and does not mean the Provider has independently verified each consent record.\n\n## 5. Confidentiality and personnel\n5.1 The Provider will ensure that persons authorised to access Customer Personal Data are subject to appropriate confidentiality obligations.\n\n5.2 Access by the Provider will be limited to what is reasonably necessary for service delivery, support, security, maintenance and legal compliance, and will be subject to access controls appropriate to the risk.\n\n5.3 The Provider will not sell Customer Personal Data or use it for unrelated advertising. Any separate analytics or product-improvement use involving personal data must be assessed, disclosed and legally supported before implementation.\n\n## 6. Security measures\n6.1 The Provider will implement and maintain reasonable technical and organisational measures appropriate to the nature of the data and risks, taking account of the actual architecture and available controls.\n\n6.2 The current architecture identified for ClassBandhu includes Supabase/PostgreSQL, Supabase Auth, row-level security (RLS), role checks and database functions/RPCs, with the web application hosted on Netlify. These facts do not, by themselves, prove that every control is correctly configured or that a certification exists.\n\n6.3 The Provider''s security schedule is in Annex 2. It must be completed only after current configuration is verified. No unsupported claim is made about encryption algorithms, penetration testing, certifications, backup frequency, disaster recovery or uptime.\n\n6.4 The Institute will use strong unique passwords, protect devices and credentials, promptly remove former users, review role assignments and report suspected compromise without undue delay.\n\n## 7. Subprocessors\n7.1 The Provider may use subprocessors only where necessary to provide the Platform and subject to appropriate written confidentiality, security and data-protection obligations.\n\n7.2 Current known infrastructure providers are:\n- **Supabase** — authentication, database and related backend services.\n- **Netlify** — web application hosting/deployment.\n\n7.3 The exact legal contracting entities, service plans, subprocessor lists, data locations, support access, backup locations, retention, and provider DPA terms have not been fully verified in the project record. The Provider must verify and list the relevant entities and terms in Annex 3 before signature.\n\n7.4 The Provider will give the Institute notice of material intended changes to subprocessors using [APPROVED NOTICE CHANNEL / PERIOD]. The Institute may raise a reasoned data-protection objection within [OBJECTION PERIOD]. The Parties will work in good faith to resolve it; any termination/refund remedy must be approved in the commercial terms.\n\n## 8. Data subject requests\n8.1 The Institute is responsible for responding to requests concerning Customer Personal Data where it is the Data Fiduciary/controller.\n\n8.2 Taking account of the nature of processing, the Provider will provide reasonable assistance, through available product functions and support processes, to help the Institute respond to requests for access, correction, completion, updating, erasure, withdrawal of consent and grievance handling as applicable.\n\n8.3 If the Provider receives a request directly from a student, parent/guardian or other data subject relating to Customer Personal Data, it will, where appropriate, direct the requester to the Institute and notify the Institute without undue delay, unless prohibited by law.\n\n8.4 The Provider may verify the identity and authority of a requester before disclosing, correcting, exporting or deleting data. The Parties should avoid collecting unnecessary identity documents.\n\n## 9. Personal data incidents and breach cooperation\n9.1 The Provider will maintain an incident-response process proportionate to the service and will notify the Institute without undue delay after becoming aware of a confirmed personal-data breach affecting Customer Personal Data, using the contact channel in Annex 4.\n\n9.2 The notice should, to the extent known and legally permissible, describe the nature of the incident, affected data/categories, likely consequences, containment/remediation steps and a contact for follow-up. Information may be provided in phases as the investigation progresses.\n\n9.3 The Parties will cooperate in investigation, evidence preservation, risk assessment, mitigation and legally required notifications. The Institute remains responsible for notifications it must make as Data Fiduciary; the Provider will provide reasonable assistance and information in its possession.\n\n9.4 The Provider will not make a public statement identifying the Institute without its consent unless required by law or necessary to protect individuals or the Platform.\n\n9.5 The incident-response owner, contact procedure, internal escalation and notification deadlines must be operationally approved before signature. This DPA does not invent a statutory notification deadline.\n\n## 10. Retention, return and deletion\n10.1 The Provider will retain Customer Personal Data only for the service term and as otherwise required by documented instructions, applicable law, security needs, dispute resolution or legal hold.\n\n10.2 On expiry or termination, at the Institute''s choice and subject to technical capability, the Provider will make available an export of Customer Personal Data or delete/return it within the period specified in Annex 5. The Institute must contact the Provider through the verified privacy/support route to request export or deletion; no export format or completion time is promised until Annex 5 and the technical workflow are approved.\n\n10.3 The Provider may retain limited records required for accounting, security, fraud prevention, legal compliance, dispute resolution or legal claims. Such records will be access-restricted and retained only for the relevant purpose.\n\n10.4 Backups and disaster-recovery copies may not be immediately alterable at an individual-record level. Backup expiry/deletion timing must be stated only after provider and platform configuration are verified. Any retained backup data remains protected and must not be restored into active use except for recovery, security or legal purposes.\n\n10.5 Suspension for non-payment does not automatically delete Customer Personal Data. The proposed subscription rule provides seven calendar days after the due date, with the due date as day zero and a proposed 23:59:59 IST deadline on day seven (timezone and billing implementation require approval). A successful payment made by the deadline and supported by transaction evidence submitted by that deadline must not result in suspension solely because Provider verification is still pending. Partial payments, disputed invoices and reversals are handled under the Terms and approved billing procedure. During suspension, ordinary ERP access may be restricted, but the Institute retains a verified route to submit privacy/deletion requests and request an available export, subject to security, technical and legal constraints.\n\n## 11. Audit and compliance information\n11.1 On reasonable written request, the Provider will make available information reasonably necessary to demonstrate compliance with this DPA, subject to confidentiality, security and protection of other customers.\n\n11.2 Any audit must be reasonable in scope, frequency, notice and cost; avoid access to other Institutes'' data; and not compromise system security. The Parties may first use available policies, provider reports and written questionnaires.\n\n11.3 Any independent audit or onsite inspection process must be agreed in Annex 6. No certification or audit report is promised by this draft.\n\n## 12. International processing and data location\nThe development and production Supabase project metadata previously inspected reported the region `ap-northeast-1` (Tokyo). This is not proof of the location of all data copies, backups, logs, provider support access, Netlify processing or every subprocessor. The Parties must verify current provider terms and data-location information before making a transfer or India-only hosting claim.\n\nThe Provider will disclose known processing locations and material cross-border processing in Annex 3 and will comply with applicable transfer restrictions and instructions as legally required.\n\n## 13. Liability and precedence\nLiability, indemnities, caps, exclusions and insurance requirements must be set out in the signed Terms/order form after legal review. This draft does not create an unapproved monetary cap or indemnity.\n\nIf this DPA conflicts with the Terms on processor handling of Customer Personal Data, this DPA controls for that subject matter. The Terms otherwise remain in effect.\n\n## 14. Contact and notices\nProvider privacy contact: **Tirth Patel — info.classbandhu@gmail.com**  \nInstitute privacy contact: [INSTITUTE CONTACT / EMAIL TO BE COMPLETED]\n\n## 15. Signatures / electronic acceptance\nThis DPA is mandatory for every Institute workspace that uses ClassBandhu and is accepted through the single first Institute-creation policy declaration checkbox, which also covers the current Terms & Conditions and Acceptable Use Policy and acknowledges the Privacy Policy. It is a linked document in that bundle, not a fourth checkbox. Before the user selects the checkbox, the interface must clearly list the DPA title/version and provide access to its full text. The server must record a distinct DPA acceptance evidence item (document key, version and hash) associated with the same user action, authenticated actor, Institute ID, server timestamp and source. There is no “no DPA applies” branch. Do not activate this workflow until the DPA is final, counsel-approved and the acceptance authority/evidence mechanism are approved.\n\n---\n\n### 15.1 Existing Institutes and owner changes\nAn Institute workspace created before this DPA mechanism is activated, and any Institute whose Institute Owner changes, must also be covered by the DPA. The Institute Owner must accept the same document bundle and make the same three declarations for that Institute through a one-time login confirmation step (Consent Implementation Specification §5.5). Staff users such as teachers and accountants cannot accept the DPA or make these declarations for an Institute, and a Super Admin cannot accept on an owner''s behalf. The transition period and notices before workspace access is restricted if the confirmation is not made are **[TRANSITION PERIOD AND NOTICE — TO BE APPROVED]**. Counsel must advise on the position for any processing that occurs before acceptance.\n\n## Annex 1 — Processing particulars\n| Item | Description |\n|---|---|\n| Subject matter | Provision of ClassBandhu tuition/institute ERP services |\n| Duration | Subscription/service term plus approved return/deletion and legal-retention period |\n| Nature of processing | Collection by Institute users, entry, storage, retrieval, organisation, display, updating, export, support, security and deletion where available |\n| Purposes | Student/institute administration, admissions, course/batch management, fees, payments, receipts, attendance, reminders and reports |\n| Data subjects | Students (including children), parents/guardians, Institute owners, teachers, accountants and other authorised staff |\n| Data categories | Student name and identifiers, parent name/contact, student mobile/email, address field, course/batch/admission data, fee/discount/due data, attendance, payment/allocation/receipt records, reminder logs, Institute profile and authorised-user records |\n| Special categories | No special-category/biometric data is identified as a current intended feature. Reassess if features change. |\n| Frequency | Continuous/periodic as users operate the Platform |\n\n## Annex 2 — Security measures (verification required)\n- Authentication through Supabase Auth; verify current password, MFA and recovery configuration.\n- PostgreSQL row-level security and tenant-scoped access; test every table, view, RPC and role boundary.\n- Least-privilege access for Operator/support personnel; document any break-glass access.\n- Secrets management; never expose service-role keys in browser code or source control.\n- Secure development and review of migrations; development-first testing and explicit production release approval.\n- Logging and audit trails for sensitive administrative and financial actions, subject to data minimisation and retention.\n- Incident response, vulnerability handling and access revocation procedures.\n- Backup, restore, encryption in transit/at rest, monitoring, and recovery controls: **verify actual provider/service configuration before representing as implemented**.\n\n## Annex 3 — Subprocessor register (must be completed)\n| Provider | Function | Known location evidence | Open verification |\n|---|---|---|---|\n| Supabase | Auth, database/backend | Project metadata previously showed Tokyo (`ap-northeast-1`) | Contracting entity, service region for all components, backups, logs, support access, DPA and subprocessor list |\n| Netlify | Web hosting/deployment | Not established in available audit | Contracting entity, processing locations, logs, forms, support access, DPA and subprocessor list |\n| Email provider | Privacy/support notifications | Gmail address confirmed; processing terms not audited | Confirm Google Workspace/Gmail account type, data handling and access controls before formal register |\n| Other providers | To be verified | Unknown | Review source code, integrations, DNS, logs and vendor contracts |\n\n## Annex 4 — Incident contacts and escalation\n- Provider incident owner: Tirth Patel.\n- Provider contact: info.classbandhu@gmail.com.\n- Institute incident contact: [REQUIRED].\n- Secondary emergency route: [APPROVE AND TEST].\n- Internal triage and escalation owner: [DOCUMENT].\n- Statutory notification decision owner and counsel contact: [DOCUMENT].\n\n## Annex 5 — Return/deletion settings\n- Export format(s): [VERIFY].\n- Institute request verification: registered Institute Owner / authorised contact, with identity and authority checks.\n- Export window after termination: [APPROVE].\n- Active-system deletion target after approved trigger: [APPROVE AFTER TECHNICAL TEST].\n- Backup expiry/deletion: [VERIFY WITH SUPABASE/NETLIFY AND CONFIGURATION].\n- Legal hold and financial record exceptions: retained/restricted as legally necessary.\n\n## Annex 6 — Audit process\n- Written request notice: [APPROVE].\n- Frequency: [APPROVE].\n- Scope and evidence format: [APPROVE].\n- Costs and confidentiality: [APPROVE].\n","is_required":false}]'::jsonb)
 AS x(slug text,title text,version text,body_markdown text,is_required boolean);

CREATE OR REPLACE FUNCTION private.record_legal_acceptance(
 p_user_id uuid,p_user_email text,p_document_id uuid,p_method text,p_user_agent text DEFAULT NULL,
 p_scope text DEFAULT 'user',p_institute_id uuid DEFAULT NULL,p_acceptance_type text DEFAULT NULL,
 p_source text DEFAULT NULL,p_actor_role text DEFAULT NULL,p_action_id uuid DEFAULT NULL
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE d record; rows_inserted integer;
BEGIN
 IF p_user_id IS NULL THEN RAISE EXCEPTION 'Acceptance actor is required.'; END IF;
 IF p_scope NOT IN('user','institute') OR (p_scope='user' AND p_institute_id IS NOT NULL) OR (p_scope='institute' AND p_institute_id IS NULL) THEN
  RAISE EXCEPTION 'Invalid legal acceptance scope.';
 END IF;
 IF p_scope='institute' AND NOT EXISTS(SELECT 1 FROM public.institute_members m WHERE m.institute_id=p_institute_id AND m.user_id=p_user_id AND m.role='owner') THEN
  RAISE EXCEPTION 'Only the current Institute Owner may record Institute legal acceptance.';
 END IF;
 SELECT id,slug,title,version,locale,content_sha256 INTO d FROM public.legal_documents WHERE id=p_document_id AND status='published';
 IF d.id IS NULL THEN RAISE EXCEPTION 'The selected legal document is not currently published.'; END IF;
 INSERT INTO public.user_legal_acceptances(user_id,user_email,document_id,document_slug,document_title,document_version,document_locale,content_sha256,
  acceptance_scope,institute_id,acceptance_method,user_agent,acceptance_type,acceptance_source,actor_role,action_id,accepted_at)
 VALUES(p_user_id,COALESCE(NULLIF(trim(p_user_email),''),'[email unavailable]'),d.id,d.slug,d.title,d.version,d.locale,d.content_sha256,
  p_scope,p_institute_id,p_method,NULLIF(left(COALESCE(p_user_agent,''),500),''),
  COALESCE(p_acceptance_type,CASE d.slug WHEN 'terms-of-service' THEN 'terms_acceptance' WHEN 'acceptable-use-policy' THEN 'aup_acceptance'
   WHEN 'privacy-policy' THEN 'privacy_acknowledgement' WHEN 'data-processing-agreement' THEN 'dpa_acceptance' ELSE NULL END),
  COALESCE(p_source,CASE p_method WHEN 'signup' THEN 'signup' WHEN 'institute_legal_bundle' THEN 'institute_creation' ELSE 'login_gate' END),
  p_actor_role,p_action_id,now()) ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS rows_inserted=ROW_COUNT;
 IF rows_inserted=0 AND NOT EXISTS(SELECT 1 FROM public.user_legal_acceptances a WHERE a.user_id=p_user_id AND a.document_id=d.id
   AND a.acceptance_scope=p_scope AND a.institute_id IS NOT DISTINCT FROM p_institute_id AND a.content_sha256=d.content_sha256) THEN
  RAISE EXCEPTION 'Legal acceptance evidence could not be recorded.';
 END IF;
END;$function$;

CREATE OR REPLACE FUNCTION private.capture_signup_legal_acceptance()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE t uuid; p uuid; u uuid; pr record; updates_ok boolean:=COALESCE(NEW.raw_user_meta_data->>'legal_product_updates','false')='true'; has_meta boolean;
BEGIN
 has_meta:=NEW.raw_user_meta_data ? 'legal_terms_accepted' OR NEW.raw_user_meta_data ? 'legal_privacy_acknowledged'
  OR NEW.raw_user_meta_data ? 'legal_aup_accepted' OR NEW.raw_user_meta_data ? 'legal_terms_document_id'
  OR NEW.raw_user_meta_data ? 'legal_privacy_document_id' OR NEW.raw_user_meta_data ? 'legal_aup_document_id';
 IF NOT has_meta THEN RETURN NEW; END IF;
 IF COALESCE(NEW.raw_user_meta_data->>'legal_terms_accepted','false')<>'true'
  OR COALESCE(NEW.raw_user_meta_data->>'legal_privacy_acknowledged','false')<>'true'
  OR COALESCE(NEW.raw_user_meta_data->>'legal_aup_accepted','false')<>'true' THEN
  RAISE EXCEPTION 'Accept the current Terms, Acceptable Use Policy and Privacy Policy before creating this account.';
 END IF;
 SELECT id INTO t FROM public.legal_documents WHERE slug='terms-of-service' AND locale='en-IN' AND status='published' AND is_required ORDER BY published_at DESC LIMIT 1;
 SELECT id INTO p FROM public.legal_documents WHERE slug='privacy-policy' AND locale='en-IN' AND status='published' AND is_required ORDER BY published_at DESC LIMIT 1;
 SELECT id INTO u FROM public.legal_documents WHERE slug='acceptable-use-policy' AND locale='en-IN' AND status='published' AND is_required ORDER BY published_at DESC LIMIT 1;
 IF t IS NULL OR p IS NULL OR u IS NULL OR NULLIF(NEW.raw_user_meta_data->>'legal_terms_document_id','') IS DISTINCT FROM t::text
  OR NULLIF(NEW.raw_user_meta_data->>'legal_privacy_document_id','') IS DISTINCT FROM p::text
  OR NULLIF(NEW.raw_user_meta_data->>'legal_aup_document_id','') IS DISTINCT FROM u::text THEN
  RAISE EXCEPTION 'The required legal documents changed or are unavailable. Reload and review the current versions.';
 END IF;
 PERFORM private.record_legal_acceptance(NEW.id,NEW.email,t,'signup',NEW.raw_user_meta_data->>'legal_acceptance_user_agent','user',NULL,'terms_acceptance','signup',NULL,gen_random_uuid());
 PERFORM private.record_legal_acceptance(NEW.id,NEW.email,u,'signup',NEW.raw_user_meta_data->>'legal_acceptance_user_agent','user',NULL,'aup_acceptance','signup',NULL,gen_random_uuid());
 PERFORM private.record_legal_acceptance(NEW.id,NEW.email,p,'signup',NEW.raw_user_meta_data->>'legal_acceptance_user_agent','user',NULL,'privacy_acknowledgement','signup',NULL,gen_random_uuid());
 SELECT id,version,content_sha256 INTO pr FROM public.legal_documents WHERE id=p;
 INSERT INTO public.privacy_consent_events(user_id,user_email,purpose_key,purpose_description,granted,privacy_document_id,privacy_document_version,privacy_document_sha256,consent_method)
 VALUES(NEW.id,COALESCE(NEW.email,'[email unavailable]'),'product_updates','Receive optional ClassBandhu product news and release updates by email.',
  updates_ok,pr.id,pr.version,pr.content_sha256,'signup');
 RETURN NEW;
END;$function$;

CREATE OR REPLACE FUNCTION public.get_my_legal_status()
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE uid uuid:=auth.uid(); req jsonb; missing jsonb;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required.'; END IF;
 WITH d AS(SELECT DISTINCT ON(slug) id,slug,title,version,locale,content_sha256,is_test_only FROM public.legal_documents
  WHERE status='published' AND is_required AND locale='en-IN' AND slug IN('terms-of-service','acceptable-use-policy','privacy-policy')
  ORDER BY slug,published_at DESC,created_at DESC)
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'slug',slug,'title',title,'version',version,'locale',locale,'content_sha256',content_sha256,'is_test_only',is_test_only) ORDER BY slug),'[]'),
  COALESCE(jsonb_agg(slug) FILTER(WHERE NOT EXISTS(SELECT 1 FROM public.user_legal_acceptances a WHERE a.user_id=uid AND a.document_id=d.id AND a.acceptance_scope='user' AND a.content_sha256=d.content_sha256)),'[]')
 INTO req,missing FROM d;
 IF jsonb_array_length(COALESCE(req,'[]'))<>3 THEN
  RETURN jsonb_build_object('required_documents',COALESCE(req,'[]'),'missing_document_slugs',jsonb_build_array('terms-of-service','acceptable-use-policy','privacy-policy'));
 END IF;
 RETURN jsonb_build_object('required_documents',req,'missing_document_slugs',COALESCE(missing,'[]'));
END;$function$;

CREATE OR REPLACE FUNCTION public.accept_current_legal_documents(p_acceptance_method text DEFAULT 'required_reacceptance',p_user_agent text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE uid uuid:=auth.uid(); email_addr text; d record; action uuid:=gen_random_uuid(); n integer;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required.'; END IF;
 IF p_acceptance_method NOT IN('required_reacceptance','privacy_preferences') THEN RAISE EXCEPTION 'Invalid acceptance method.'; END IF;
 SELECT email INTO email_addr FROM auth.users WHERE id=uid;
 SELECT count(DISTINCT slug) INTO n FROM public.legal_documents WHERE status='published' AND is_required AND locale='en-IN'
  AND slug IN('terms-of-service','acceptable-use-policy','privacy-policy');
 IF n<>3 THEN RAISE EXCEPTION 'The current Terms, AUP and Privacy Policy must all be published.'; END IF;
 FOR d IN SELECT DISTINCT ON(slug) id,slug FROM public.legal_documents WHERE status='published' AND is_required AND locale='en-IN'
  AND slug IN('terms-of-service','acceptable-use-policy','privacy-policy') ORDER BY slug,published_at DESC,created_at DESC LOOP
  PERFORM private.record_legal_acceptance(uid,email_addr,d.id,p_acceptance_method,p_user_agent,'user',NULL,NULL,'login_gate',NULL,action);
 END LOOP;
 RETURN public.get_my_legal_status();
END;$function$;

CREATE OR REPLACE FUNCTION private.has_current_account_legal_acceptance(p_user_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $function$
 WITH d AS(SELECT DISTINCT ON(slug) id,slug,content_sha256 FROM public.legal_documents WHERE status='published' AND is_required AND locale='en-IN'
  AND slug IN('terms-of-service','acceptable-use-policy','privacy-policy') ORDER BY slug,published_at DESC,created_at DESC)
 SELECT count(*)=3 FROM d WHERE EXISTS(SELECT 1 FROM public.user_legal_acceptances a WHERE a.user_id=p_user_id AND a.document_id=d.id AND a.acceptance_scope='user' AND a.content_sha256=d.content_sha256);
$function$;

CREATE OR REPLACE FUNCTION private.has_current_institute_legal_acceptance(p_user_id uuid,p_institute_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $function$
 WITH d AS(SELECT DISTINCT ON(slug) id,slug,content_sha256 FROM public.legal_documents WHERE status='published' AND locale='en-IN'
  AND slug IN('terms-of-service','acceptable-use-policy','privacy-policy','data-processing-agreement') ORDER BY slug,published_at DESC,created_at DESC)
 SELECT count(*)=4
  AND EXISTS(SELECT 1 FROM public.institute_legal_declarations x WHERE x.actor_user_id=p_user_id AND x.institute_id=p_institute_id AND x.declaration_type='institute_authority')
  AND EXISTS(SELECT 1 FROM public.institute_legal_declarations x WHERE x.actor_user_id=p_user_id AND x.institute_id=p_institute_id AND x.declaration_type='data_authority_attestation')
 FROM d WHERE EXISTS(SELECT 1 FROM public.user_legal_acceptances a WHERE a.user_id=p_user_id AND a.institute_id=p_institute_id AND a.document_id=d.id AND a.acceptance_scope='institute' AND a.content_sha256=d.content_sha256);
$function$;

CREATE OR REPLACE FUNCTION private.is_member_of(_institute_id uuid,_required_roles text[] DEFAULT ARRAY['owner','accountant','teacher']::text[])
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $function$
 SELECT auth.uid() IS NOT NULL
 AND EXISTS(SELECT 1 FROM public.institute_members m WHERE m.institute_id=_institute_id AND m.user_id=auth.uid() AND m.role=ANY(_required_roles)
  AND private.has_current_account_legal_acceptance(auth.uid())
  AND (m.role<>'owner' OR now()<(SELECT activated_at+make_interval(days=>grace_days) FROM private.legal_transition_config WHERE singleton=true)
   OR private.has_current_institute_legal_acceptance(auth.uid(),_institute_id)))
 AND COALESCE((SELECT c.access_status FROM private.platform_institute_controls c WHERE c.institute_id=_institute_id),'active')='active'
 AND COALESCE((SELECT c.subscription_status FROM private.platform_institute_controls c WHERE c.institute_id=_institute_id),'trial') IN('trial','active','past_due')
 AND COALESCE((SELECT c.starts_at FROM private.platform_institute_controls c WHERE c.institute_id=_institute_id),'-infinity'::timestamptz)<=now()
 AND COALESCE((SELECT c.expires_at FROM private.platform_institute_controls c WHERE c.institute_id=_institute_id),'infinity'::timestamptz)>now();
$function$;

CREATE OR REPLACE FUNCTION public.get_my_dpa_requirements()
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE uid uuid:=auth.uid(); email_addr text; docs jsonb; dpa jsonb; institutes jsonb; missing jsonb; deadline timestamptz; n integer;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required.'; END IF;
 SELECT email INTO email_addr FROM auth.users WHERE id=uid;
 SELECT activated_at+make_interval(days=>grace_days) INTO deadline FROM private.legal_transition_config WHERE singleton=true;
 WITH d AS(SELECT DISTINCT ON(slug) id,slug,title,version,locale,content_sha256,is_test_only FROM public.legal_documents
  WHERE status='published' AND locale='en-IN' AND slug IN('terms-of-service','acceptable-use-policy','privacy-policy','data-processing-agreement')
  ORDER BY slug,published_at DESC,created_at DESC)
 SELECT count(*),COALESCE(jsonb_agg(jsonb_build_object('id',id,'slug',slug,'title',title,'version',version,'locale',locale,'content_sha256',content_sha256,'is_test_only',is_test_only) ORDER BY slug),'[]')
 INTO n,docs FROM d;
 SELECT to_jsonb(z) INTO dpa FROM(SELECT id,title,version,locale,content_sha256,published_at,is_test_only FROM public.legal_documents
  WHERE slug='data-processing-agreement' AND status='published' AND locale='en-IN' ORDER BY published_at DESC LIMIT 1) z;
 IF n<>4 THEN
  SELECT COALESCE(jsonb_agg(jsonb_build_object('institute_id',m.institute_id,'institute_name',i.name,'accepted',false,'accepted_by',NULL,'accepted_at',NULL) ORDER BY i.name),'[]'),
   COALESCE(jsonb_agg(m.institute_id),'[]') INTO institutes,missing
  FROM public.institute_members m JOIN public.institutes i ON i.id=m.institute_id WHERE m.user_id=uid AND m.role='owner';
 ELSE
  SELECT COALESCE(jsonb_agg(jsonb_build_object('institute_id',m.institute_id,'institute_name',i.name,
    'accepted',private.has_current_institute_legal_acceptance(uid,m.institute_id),
    'accepted_by',CASE WHEN private.has_current_institute_legal_acceptance(uid,m.institute_id) THEN email_addr ELSE NULL END,
    'accepted_at',(SELECT max(a.accepted_at) FROM public.user_legal_acceptances a WHERE a.user_id=uid AND a.institute_id=m.institute_id AND a.acceptance_scope='institute')) ORDER BY i.name),'[]'),
   COALESCE(jsonb_agg(m.institute_id) FILTER(WHERE NOT private.has_current_institute_legal_acceptance(uid,m.institute_id)),'[]')
  INTO institutes,missing FROM public.institute_members m JOIN public.institutes i ON i.id=m.institute_id WHERE m.user_id=uid AND m.role='owner';
 END IF;
 RETURN jsonb_build_object('document',dpa,'documents',COALESCE(docs,'[]'),'institutes',COALESCE(institutes,'[]'),
  'missing_institute_ids',COALESCE(missing,'[]'),'transition_deadline_at',deadline,'transition_days',14);
END;$function$;

CREATE OR REPLACE FUNCTION public.get_institute_dpa_status(p_institute_id uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE d record; a record;
BEGIN
 IF auth.uid() IS NULL OR NOT private.is_member_of(p_institute_id,ARRAY['owner']::text[]) THEN RAISE EXCEPTION 'Active institute owner access is required.'; END IF;
 SELECT id,title,version,content_sha256,published_at INTO d FROM public.legal_documents WHERE slug='data-processing-agreement' AND status='published' ORDER BY published_at DESC LIMIT 1;
 IF d.id IS NULL THEN RETURN jsonb_build_object('document',NULL,'accepted',false); END IF;
 SELECT user_email,accepted_at INTO a FROM public.user_legal_acceptances WHERE user_id=auth.uid() AND document_id=d.id AND institute_id=p_institute_id AND acceptance_scope='institute' ORDER BY accepted_at DESC LIMIT 1;
 RETURN jsonb_build_object('document',jsonb_build_object('id',d.id,'title',d.title,'version',d.version,'content_sha256',d.content_sha256,'published_at',d.published_at),
  'accepted',a.accepted_at IS NOT NULL,'accepted_by',a.user_email,'accepted_at',a.accepted_at);
END;$function$;

CREATE OR REPLACE FUNCTION public.create_institute_with_legal_bundle(
 p_name text,p_slug text,p_document_ids jsonb,p_accept_authority boolean,p_accept_data_authority boolean,
 p_user_agent text DEFAULT NULL,p_currency_symbol text DEFAULT '₹',p_receipt_prefix text DEFAULT 'REC'
) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE uid uuid:=auth.uid(); email_addr text; new_id uuid; d record; action uuid:=gen_random_uuid(); src text:='institute_creation';
 authority_text text:='I confirm that I am authorised to create and manage this institution''s account and to provide the institution''s information to ClassBandhu for the ERP service.';
 data_text text:='I confirm that, wherever required by applicable law, the institution has obtained the necessary consent or other lawful authorisation from parents or legal guardians for collecting and sharing student personal information with ClassBandhu to provide the ERP service.';
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required.'; END IF;
 IF NOT private.has_current_account_legal_acceptance(uid) THEN RAISE EXCEPTION 'Complete the current Terms, AUP and Privacy acceptance first.'; END IF;
 IF p_accept_authority IS DISTINCT FROM true OR p_accept_data_authority IS DISTINCT FROM true THEN RAISE EXCEPTION 'All three Institute confirmations are required.'; END IF;
 FOR d IN SELECT DISTINCT ON(slug) id,slug FROM public.legal_documents WHERE status='published' AND locale='en-IN'
  AND slug IN('terms-of-service','acceptable-use-policy','privacy-policy','data-processing-agreement') ORDER BY slug,published_at DESC,created_at DESC LOOP
  IF NULLIF(p_document_ids->>d.slug,'') IS DISTINCT FROM d.id::text THEN RAISE EXCEPTION 'The current document bundle changed. Reload and review again.'; END IF;
 END LOOP;
 IF (SELECT count(*) FROM public.legal_documents WHERE status='published' AND locale='en-IN' AND slug IN('terms-of-service','acceptable-use-policy','privacy-policy','data-processing-agreement'))<>4 THEN
  RAISE EXCEPTION 'The current Institute legal bundle is incomplete.';
 END IF;
 new_id:=public.create_institute_atomic(p_name,p_slug,p_currency_symbol,p_receipt_prefix);
 SELECT email INTO email_addr FROM auth.users WHERE id=uid;
 FOR d IN SELECT DISTINCT ON(slug) id,slug FROM public.legal_documents WHERE status='published' AND locale='en-IN'
  AND slug IN('terms-of-service','acceptable-use-policy','privacy-policy','data-processing-agreement') ORDER BY slug,published_at DESC,created_at DESC LOOP
  PERFORM private.record_legal_acceptance(uid,email_addr,d.id,'institute_legal_bundle',p_user_agent,'institute',new_id,NULL,src,'owner',action);
 END LOOP;
 INSERT INTO public.institute_legal_declarations(institute_id,actor_user_id,actor_email,actor_role,declaration_type,declaration_text,content_sha256,source,action_id)
 VALUES
 (new_id,uid,COALESCE(email_addr,'[email unavailable]'),'owner','institute_authority',authority_text,encode(extensions.digest(authority_text,'sha256'),'hex'),src,action),
 (new_id,uid,COALESCE(email_addr,'[email unavailable]'),'owner','data_authority_attestation',data_text,encode(extensions.digest(data_text,'sha256'),'hex'),src,action);
 RETURN new_id;
END;$function$;

CREATE OR REPLACE FUNCTION public.accept_current_institute_legal_bundle(
 p_institute_id uuid,p_document_ids jsonb,p_accept_authority boolean,p_accept_data_authority boolean,p_user_agent text DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE uid uuid:=auth.uid(); email_addr text; d record; action uuid:=gen_random_uuid(); n integer;
 authority_text text:='I confirm that I am authorised to create and manage this institution''s account and to provide the institution''s information to ClassBandhu for the ERP service.';
 data_text text:='I confirm that, wherever required by applicable law, the institution has obtained the necessary consent or other lawful authorisation from parents or legal guardians for collecting and sharing student personal information with ClassBandhu to provide the ERP service.';
BEGIN
 IF uid IS NULL OR NOT EXISTS(SELECT 1 FROM public.institute_members m WHERE m.institute_id=p_institute_id AND m.user_id=uid AND m.role='owner') THEN
  RAISE EXCEPTION 'Only the current Institute Owner may accept this Institute legal bundle.';
 END IF;
 IF NOT private.has_current_account_legal_acceptance(uid) THEN RAISE EXCEPTION 'Complete your account-level Terms, AUP and Privacy acceptance first.'; END IF;
 IF p_accept_authority IS DISTINCT FROM true OR p_accept_data_authority IS DISTINCT FROM true THEN RAISE EXCEPTION 'All three Institute confirmations are required.'; END IF;
 SELECT count(*) INTO n FROM public.legal_documents WHERE status='published' AND locale='en-IN' AND slug IN('terms-of-service','acceptable-use-policy','privacy-policy','data-processing-agreement');
 IF n<>4 THEN RAISE EXCEPTION 'The current Institute legal bundle is incomplete.'; END IF;
 FOR d IN SELECT DISTINCT ON(slug) id,slug FROM public.legal_documents WHERE status='published' AND locale='en-IN'
  AND slug IN('terms-of-service','acceptable-use-policy','privacy-policy','data-processing-agreement') ORDER BY slug,published_at DESC,created_at DESC LOOP
  IF NULLIF(p_document_ids->>d.slug,'') IS DISTINCT FROM d.id::text THEN RAISE EXCEPTION 'A document changed. Reload and review all current documents.'; END IF;
 END LOOP;
 SELECT email INTO email_addr FROM auth.users WHERE id=uid;
 FOR d IN SELECT DISTINCT ON(slug) id,slug FROM public.legal_documents WHERE status='published' AND locale='en-IN'
  AND slug IN('terms-of-service','acceptable-use-policy','privacy-policy','data-processing-agreement') ORDER BY slug,published_at DESC,created_at DESC LOOP
  PERFORM private.record_legal_acceptance(uid,email_addr,d.id,'institute_legal_bundle',p_user_agent,'institute',p_institute_id,NULL,'login_gate','owner',action);
 END LOOP;
 INSERT INTO public.institute_legal_declarations(institute_id,actor_user_id,actor_email,actor_role,declaration_type,declaration_text,content_sha256,source,action_id)
 VALUES
 (p_institute_id,uid,COALESCE(email_addr,'[email unavailable]'),'owner','institute_authority',authority_text,encode(extensions.digest(authority_text,'sha256'),'hex'),'login_gate',action),
 (p_institute_id,uid,COALESCE(email_addr,'[email unavailable]'),'owner','data_authority_attestation',data_text,encode(extensions.digest(data_text,'sha256'),'hex'),'login_gate',action);
 RETURN public.get_my_dpa_requirements();
END;$function$;

REVOKE ALL ON FUNCTION public.accept_current_institute_dpa(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_my_dpa_requirements() TO authenticated;
REVOKE ALL ON FUNCTION public.create_institute_with_dpa_acceptance(text,text,uuid,text,text,text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.create_institute_atomic(text,text,text,text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.create_institute_with_legal_bundle(text,text,jsonb,boolean,boolean,text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_institute_with_legal_bundle(text,text,jsonb,boolean,boolean,text,text,text) TO authenticated;
REVOKE ALL ON FUNCTION public.accept_current_institute_legal_bundle(uuid,jsonb,boolean,boolean,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.accept_current_institute_legal_bundle(uuid,jsonb,boolean,boolean,text) TO authenticated;
COMMIT;
